export function initInteractions(){
 const reduced=matchMedia('(prefers-reduced-motion: reduce)'),fine=matchMedia('(hover:hover) and (pointer:fine)');
 const eligible='.button,.text-button,.icon-button,.round-button,.desktop-nav a,.mobile-nav a,.grade-tabs button,.journal-tools button,.book-navigation button,.scope-slides button,.scope-objectives button,.scope-assist,.scope-capture button,.scope-toggles button,.scope-pan button,.scope-entry button,.scope-exit,.specimen-switch button,.lab-grade-tabs button,.profile-button,.studio-button,.studio-text-button,.studio-tablist button,.gene-challenges button,.scale-stops button,.immune-choices button,.scientist-picker button,.field-study-picker button,.campus-button,.campus-tabs button,.biolab-tools button,.quest-picker button,.everyday-picker button,.map-filters button,.career-picker button';
 const layer=document.createElement('div');layer.className='interaction-bubbles';layer.setAttribute('aria-hidden','true');document.body.append(layer);
 let last=0,lastElement=null;
 function bubbles(el,x,y,burst=false){if(reduced.matches||!fine.matches||el.disabled)return;const now=performance.now();if(!burst&&now-last<140&&lastElement===el)return;last=now;lastElement=el;const host=el.closest('dialog[open]')||document.body;if(layer.parentElement!==host)host.append(layer);const origin=layer.getBoundingClientRect();const bounds=el.getBoundingClientRect();for(let i=0;i<(burst?5:3);i++){const b=document.createElement('i'),size=5+Math.random()*10;b.className='interaction-bubble';b.style.cssText=`left:${(x??bounds.left+bounds.width*(.25+Math.random()*.5))-origin.left}px;top:${(y??bounds.top+bounds.height*.6)-origin.top}px;width:${size}px;height:${size}px;--bubble-drift:${(Math.random()-.5)*65}px;--bubble-rise:${35+Math.random()*40}px;--bubble-delay:${i*65}ms`;layer.append(b);b.addEventListener('animationend',()=>b.remove(),{once:true});setTimeout(()=>b.remove(),1500)}}
 document.addEventListener('pointerover',e=>{const el=e.target.closest(eligible);if(!el||el.contains(e.relatedTarget))return;el.classList.add('has-bubble-effect');bubbles(el,e.clientX,e.clientY)});
 document.addEventListener('pointerdown',e=>{const el=e.target.closest(eligible);if(el)bubbles(el,e.clientX,e.clientY,true)});
 document.addEventListener('visibilitychange',()=>{if(document.hidden)layer.replaceChildren()});
}
